request.query:
query ClubPlayers($slug: String!) {
  football {
    club(slug: $slug) {
      activePlayers {
        nodes {
          displayName
          slug
          position
          activeInjuries {
            id
          }
          activeSuspensions {
            id
          }
          so5Scores(last: 15) {
            score
          }
        }
      }
    }
  }
}
